        // Build a lookup map: niche_no => niches.id
        $nicheIdMap = DB::table('niches')
            ->pluck('id', 'niche_no')
            ->all();

        $now = now();
        $records = [];

        foreach ($nitchesValidMembers as $row) {
            $nicheNo = (int) $row['niche_id'];

            if (!isset($nicheIdMap[$nicheNo])) {
                continue; // skip if niche_no not found in niches table
            }

            $records[] = [
                'niche_id'          => $nicheIdMap[$nicheNo],
                'permanent_grave_id'=> null,
                'member_id'         => $row['member_id'],
                'first_name'        => $row['first_name'],
                'last_name'         => $row['last_name'],
                'contact_no'        => $row['contact_no'],
                'aadhar_no'         => $row['aadhar_no'],
                'grave_type'        => 'niche',
                'member_type'       => 'external',
                'is_active'         => true,
                'created_at'        => $now,
                'updated_at'        => $now,
            ];
        }

        // Insert in chunks to avoid hitting query size limits
        foreach (array_chunk($records, 500) as $chunk) {
            DB::table('valid_members')->insert($chunk);
        }
    }
